insert into public.topics (id, slug, order_index) values ('52478e3c-3ea3-4db1-9cf0-f5db7e4c9601', 'communication-conflict', 1);
insert into public.topic_translations (topic_id, locale, title, subtitle) values ('52478e3c-3ea3-4db1-9cf0-f5db7e4c9601', 'en', 'Communication & conflict', 'How you each handle disagreement, before it becomes a bigger conversation.');
insert into public.questions (id, key, topic_id, order_index, default_importance) values ('6766f6f3-05dc-49d7-8f84-aa86998f3e69', 'comm-01', '52478e3c-3ea3-4db1-9cf0-f5db7e4c9601', 1, 'medium');
insert into public.question_translations (question_id, locale, text, starter_aligned, starter_discuss) values ('6766f6f3-05dc-49d7-8f84-aa86998f3e69', 'en', 'When something upsets you, what do you tend to do first?', 'You have landed in a similar place on this one. Compare what that would look like in an ordinary week, so the shared expectation is concrete.', 'You reach for different timings when something stings. Try agreeing on a signal that means ''not now, but soon'' — it protects both instincts.');
insert into public.question_options (question_id, key, cluster, order_index) values ('6766f6f3-05dc-49d7-8f84-aa86998f3e69', 'a', 'immediate', 1);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('6766f6f3-05dc-49d7-8f84-aa86998f3e69', 'a', 'en', 'Say it right away', 'I''d rather raise it in the moment.');
insert into public.question_options (question_id, key, cluster, order_index) values ('6766f6f3-05dc-49d7-8f84-aa86998f3e69', 'b', 'immediate', 2);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('6766f6f3-05dc-49d7-8f84-aa86998f3e69', 'b', 'en', 'Pause, then raise it', 'A few minutes to gather myself first.');
insert into public.question_options (question_id, key, cluster, order_index) values ('6766f6f3-05dc-49d7-8f84-aa86998f3e69', 'c', 'delayed', 3);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('6766f6f3-05dc-49d7-8f84-aa86998f3e69', 'c', 'en', 'Wait until things are calm', 'Later that day, or the next.');
insert into public.question_options (question_id, key, cluster, order_index) values ('6766f6f3-05dc-49d7-8f84-aa86998f3e69', 'd', 'delayed', 4);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('6766f6f3-05dc-49d7-8f84-aa86998f3e69', 'd', 'en', 'Let it pass unless it repeats', 'I''ll raise it only if it becomes a pattern.');
insert into public.questions (id, key, topic_id, order_index, default_importance) values ('85c68bdf-6ef1-46df-a981-055dd359df6b', 'comm-02', '52478e3c-3ea3-4db1-9cf0-f5db7e4c9601', 2, 'medium');
insert into public.question_translations (question_id, locale, text, starter_aligned, starter_discuss) values ('85c68bdf-6ef1-46df-a981-055dd359df6b', 'en', 'In the middle of a disagreement, what helps you most?', 'You have landed in a similar place on this one. Compare what that would look like in an ordinary week, so the shared expectation is concrete.', 'One of you settles by staying in it; the other by stepping out. Talk about what a break should look like so it doesn''t read as walking away.');
insert into public.question_options (question_id, key, cluster, order_index) values ('85c68bdf-6ef1-46df-a981-055dd359df6b', 'a', 'engage', 1);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('85c68bdf-6ef1-46df-a981-055dd359df6b', 'a', 'en', 'Talking until it''s settled', 'I don''t like leaving things open.');
insert into public.question_options (question_id, key, cluster, order_index) values ('85c68bdf-6ef1-46df-a981-055dd359df6b', 'b', 'engage', 2);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('85c68bdf-6ef1-46df-a981-055dd359df6b', 'b', 'en', 'Talking, with breaks', 'Keep going, but pause when it gets heated.');
insert into public.question_options (question_id, key, cluster, order_index) values ('85c68bdf-6ef1-46df-a981-055dd359df6b', 'c', 'space', 3);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('85c68bdf-6ef1-46df-a981-055dd359df6b', 'c', 'en', 'Time apart first', 'I need to step away before I can talk well.');
insert into public.question_options (question_id, key, cluster, order_index) values ('85c68bdf-6ef1-46df-a981-055dd359df6b', 'd', 'space', 4);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('85c68bdf-6ef1-46df-a981-055dd359df6b', 'd', 'en', 'Writing before speaking', 'I think more clearly on paper.');
insert into public.questions (id, key, topic_id, order_index, default_importance) values ('f0203f54-5df9-4c1d-bc2c-f6b62f61b0b0', 'comm-03', '52478e3c-3ea3-4db1-9cf0-f5db7e4c9601', 3, 'medium');
insert into public.question_translations (question_id, locale, text, starter_aligned, starter_discuss) values ('f0203f54-5df9-4c1d-bc2c-f6b62f61b0b0', 'en', 'If something is unresolved at bedtime, what happens?', 'You have landed in a similar place on this one. Compare what that would look like in an ordinary week, so the shared expectation is concrete.', 'This one causes more late nights than almost anything. Decide now what happens at 11pm, while neither of you is upset.');
insert into public.question_options (question_id, key, cluster, order_index) values ('f0203f54-5df9-4c1d-bc2c-f6b62f61b0b0', 'a', 'resolve', 1);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('f0203f54-5df9-4c1d-bc2c-f6b62f61b0b0', 'a', 'en', 'We stay up until it''s settled', 'I couldn''t sleep on it.');
insert into public.question_options (question_id, key, cluster, order_index) values ('f0203f54-5df9-4c1d-bc2c-f6b62f61b0b0', 'b', 'resolve', 2);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('f0203f54-5df9-4c1d-bc2c-f6b62f61b0b0', 'b', 'en', 'We set a time tomorrow', 'Named and agreed before we sleep.');
insert into public.question_options (question_id, key, cluster, order_index) values ('f0203f54-5df9-4c1d-bc2c-f6b62f61b0b0', 'c', 'rest', 3);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('f0203f54-5df9-4c1d-bc2c-f6b62f61b0b0', 'c', 'en', 'We let it rest', 'See how it feels in the morning.');
insert into public.question_options (question_id, key, cluster, order_index) values ('f0203f54-5df9-4c1d-bc2c-f6b62f61b0b0', 'd', 'rest', 4);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('f0203f54-5df9-4c1d-bc2c-f6b62f61b0b0', 'd', 'en', 'We move on', 'Most things don''t need returning to.');
insert into public.questions (id, key, topic_id, order_index, default_importance) values ('2ce3926a-221b-4c9d-b883-60099461877d', 'comm-04', '52478e3c-3ea3-4db1-9cf0-f5db7e4c9601', 4, 'medium');
insert into public.question_translations (question_id, locale, text, starter_aligned, starter_discuss) values ('2ce3926a-221b-4c9d-b883-60099461877d', 'en', 'If the marriage hit a difficult stretch, who would you talk to?', 'You have landed in a similar place on this one. Compare what that would look like in an ordinary week, so the shared expectation is concrete.', 'Who gets to know is worth settling early. Try agreeing on one person each of you could turn to, named in advance.');
insert into public.question_options (question_id, key, cluster, order_index) values ('2ce3926a-221b-4c9d-b883-60099461877d', 'a', 'closed', 1);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('2ce3926a-221b-4c9d-b883-60099461877d', 'a', 'en', 'No one outside us', 'What''s between us stays between us.');
insert into public.question_options (question_id, key, cluster, order_index) values ('2ce3926a-221b-4c9d-b883-60099461877d', 'b', 'closed', 2);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('2ce3926a-221b-4c9d-b883-60099461877d', 'b', 'en', 'One trusted person', 'A single friend or sibling I rely on.');
insert into public.question_options (question_id, key, cluster, order_index) values ('2ce3926a-221b-4c9d-b883-60099461877d', 'c', 'open', 3);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('2ce3926a-221b-4c9d-b883-60099461877d', 'c', 'en', 'Our families', 'They''d know, and they''d help.');
insert into public.question_options (question_id, key, cluster, order_index) values ('2ce3926a-221b-4c9d-b883-60099461877d', 'd', 'open', 4);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('2ce3926a-221b-4c9d-b883-60099461877d', 'd', 'en', 'An imam or counsellor', 'Someone outside the family, with experience.');
insert into public.questions (id, key, topic_id, order_index, default_importance) values ('3ced9a5d-5956-4a6e-9de8-18f447587250', 'comm-05', '52478e3c-3ea3-4db1-9cf0-f5db7e4c9601', 5, 'medium');
insert into public.question_translations (question_id, locale, text, starter_aligned, starter_discuss) values ('3ced9a5d-5956-4a6e-9de8-18f447587250', 'en', 'When you''re clearly upset, how do you want to be approached?', 'You have landed in a similar place on this one. Compare what that would look like in an ordinary week, so the shared expectation is concrete.', 'What feels like care to one person can feel like pressure to the other. Say plainly what you want the first five minutes to look like.');
insert into public.question_options (question_id, key, cluster, order_index) values ('3ced9a5d-5956-4a6e-9de8-18f447587250', 'a', 'direct', 1);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('3ced9a5d-5956-4a6e-9de8-18f447587250', 'a', 'en', 'Ask me directly', 'Just ask what''s wrong.');
insert into public.question_options (question_id, key, cluster, order_index) values ('3ced9a5d-5956-4a6e-9de8-18f447587250', 'b', 'direct', 2);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('3ced9a5d-5956-4a6e-9de8-18f447587250', 'b', 'en', 'Give me a moment, then ask', 'A little space first, then check in.');
insert into public.question_options (question_id, key, cluster, order_index) values ('3ced9a5d-5956-4a6e-9de8-18f447587250', 'c', 'wait', 3);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('3ced9a5d-5956-4a6e-9de8-18f447587250', 'c', 'en', 'Wait for me', 'I''ll come to you when I''m ready.');
insert into public.question_options (question_id, key, cluster, order_index) values ('3ced9a5d-5956-4a6e-9de8-18f447587250', 'd', 'wait', 4);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('3ced9a5d-5956-4a6e-9de8-18f447587250', 'd', 'en', 'Something kind, unspoken', 'Show care without making me explain.');
insert into public.questions (id, key, topic_id, order_index, default_importance) values ('d5bb3b5d-1837-4b90-8f4e-516c1e00b60f', 'comm-06', '52478e3c-3ea3-4db1-9cf0-f5db7e4c9601', 6, 'medium');
insert into public.question_translations (question_id, locale, text, starter_aligned, starter_discuss) values ('d5bb3b5d-1837-4b90-8f4e-516c1e00b60f', 'en', 'How do you feel about raised voices during an argument?', 'You have landed in a similar place on this one. Compare what that would look like in an ordinary week, so the shared expectation is concrete.', 'Households run at different volumes, and it''s usually inherited rather than chosen. Describe what arguments sounded like growing up before deciding what yours will sound like.');
insert into public.question_options (question_id, key, cluster, order_index) values ('d5bb3b5d-1837-4b90-8f4e-516c1e00b60f', 'a', 'low', 1);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('d5bb3b5d-1837-4b90-8f4e-516c1e00b60f', 'a', 'en', 'Never acceptable', 'It changes how safe the conversation feels.');
insert into public.question_options (question_id, key, cluster, order_index) values ('d5bb3b5d-1837-4b90-8f4e-516c1e00b60f', 'b', 'low', 2);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('d5bb3b5d-1837-4b90-8f4e-516c1e00b60f', 'b', 'en', 'Rare, not a habit', 'It happens, but it shouldn''t be normal.');
insert into public.question_options (question_id, key, cluster, order_index) values ('d5bb3b5d-1837-4b90-8f4e-516c1e00b60f', 'c', 'tolerant', 3);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('d5bb3b5d-1837-4b90-8f4e-516c1e00b60f', 'c', 'en', 'Normal where I''m from', 'Volume doesn''t mean much in my family.');
insert into public.question_options (question_id, key, cluster, order_index) values ('d5bb3b5d-1837-4b90-8f4e-516c1e00b60f', 'd', 'tolerant', 4);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('d5bb3b5d-1837-4b90-8f4e-516c1e00b60f', 'd', 'en', 'Better than silence', 'I''d rather hear it than be shut out.');
insert into public.topics (id, slug, order_index) values ('8ff239e3-f9a2-415a-ad5d-073d83646bf7', 'faith-practice', 2);
insert into public.topic_translations (topic_id, locale, title, subtitle) values ('8ff239e3-f9a2-415a-ad5d-073d83646bf7', 'en', 'Faith & practice', 'How you each practise, and what you expect of one another.');
insert into public.questions (id, key, topic_id, order_index, default_importance) values ('df6434a8-1e08-4996-aa71-03912532a2d6', 'faith-01', '8ff239e3-f9a2-415a-ad5d-073d83646bf7', 1, 'medium');
insert into public.question_translations (question_id, locale, text, starter_aligned, starter_discuss) values ('df6434a8-1e08-4996-aa71-03912532a2d6', 'en', 'How do you picture salah working in our home?', 'You have landed in a similar place on this one. Compare what that would look like in an ordinary week, so the shared expectation is concrete.', 'Praying together is a habit that forms in the first months or not at all. Try picking one prayer to start with rather than settling the whole week.');
insert into public.question_options (question_id, key, cluster, order_index) values ('df6434a8-1e08-4996-aa71-03912532a2d6', 'a', 'together', 1);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('df6434a8-1e08-4996-aa71-03912532a2d6', 'a', 'en', 'Together whenever we''re both home', 'Praying in congregation as our default.');
insert into public.question_options (question_id, key, cluster, order_index) values ('df6434a8-1e08-4996-aa71-03912532a2d6', 'b', 'together', 2);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('df6434a8-1e08-4996-aa71-03912532a2d6', 'b', 'en', 'Together for some prayers', 'Fajr and maghrib together, the rest as they fall.');
insert into public.question_options (question_id, key, cluster, order_index) values ('df6434a8-1e08-4996-aa71-03912532a2d6', 'c', 'individual', 3);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('df6434a8-1e08-4996-aa71-03912532a2d6', 'c', 'en', 'Each to our own routine', 'We pray, but not necessarily side by side.');
insert into public.question_options (question_id, key, cluster, order_index) values ('df6434a8-1e08-4996-aa71-03912532a2d6', 'd', 'individual', 4);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('df6434a8-1e08-4996-aa71-03912532a2d6', 'd', 'en', 'One leads, the other joins when they can', 'Open invitation rather than expectation.');
insert into public.questions (id, key, topic_id, order_index, default_importance) values ('2821d891-540e-4204-a83c-cd7add197b64', 'faith-02', '8ff239e3-f9a2-415a-ad5d-073d83646bf7', 2, 'medium');
insert into public.question_translations (question_id, locale, text, starter_aligned, starter_discuss) values ('2821d891-540e-4204-a83c-cd7add197b64', 'en', 'How would you want Ramadan to run in our home?', 'You have landed in a similar place on this one. Compare what that would look like in an ordinary week, so the shared expectation is concrete.', 'Ramadan is where two family traditions meet hardest. Walk through one week of it out loud — suhoor, iftar, taraweeh — before the first one arrives.');
insert into public.question_options (question_id, key, cluster, order_index) values ('2821d891-540e-4204-a83c-cd7add197b64', 'a', 'couple', 1);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('2821d891-540e-4204-a83c-cd7add197b64', 'a', 'en', 'Built around the two of us', 'Our own rhythm for suhoor and iftar.');
insert into public.question_options (question_id, key, cluster, order_index) values ('2821d891-540e-4204-a83c-cd7add197b64', 'b', 'couple', 2);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('2821d891-540e-4204-a83c-cd7add197b64', 'b', 'en', 'Ours, with family nights', 'Mostly us, with regular family gatherings.');
insert into public.question_options (question_id, key, cluster, order_index) values ('2821d891-540e-4204-a83c-cd7add197b64', 'c', 'wider', 3);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('2821d891-540e-4204-a83c-cd7add197b64', 'c', 'en', 'Mostly with extended family', 'Ramadan is a family season for me.');
insert into public.question_options (question_id, key, cluster, order_index) values ('2821d891-540e-4204-a83c-cd7add197b64', 'd', 'wider', 4);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('2821d891-540e-4204-a83c-cd7add197b64', 'd', 'en', 'Each keeping our own routine', 'Work and schedules differ; we''d adapt.');
insert into public.questions (id, key, topic_id, order_index, default_importance) values ('6e443160-fcac-4d10-a665-36453237e2ad', 'faith-03', '8ff239e3-f9a2-415a-ad5d-073d83646bf7', 3, 'medium');
insert into public.question_translations (question_id, locale, text, starter_aligned, starter_discuss) values ('6e443160-fcac-4d10-a665-36453237e2ad', 'en', 'How would you want to keep learning your deen?', 'You have landed in a similar place on this one. Compare what that would look like in an ordinary week, so the shared expectation is concrete.', 'Learning together is one of the easier habits to build early. Try one thing you could both commit to for a month, not a year.');
insert into public.question_options (question_id, key, cluster, order_index) values ('6e443160-fcac-4d10-a665-36453237e2ad', 'a', 'structured', 1);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('6e443160-fcac-4d10-a665-36453237e2ad', 'a', 'en', 'Studying together', 'Classes or a regular halaqa, as a pair.');
insert into public.question_options (question_id, key, cluster, order_index) values ('6e443160-fcac-4d10-a665-36453237e2ad', 'b', 'individual', 2);
