insert into public.question_options (question_id, key, cluster, order_index) values ('6e443160-fcac-4d10-a665-36453237e2ad', 'c', 'structured', 3);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('6e443160-fcac-4d10-a665-36453237e2ad', 'c', 'en', 'Through community', 'Whatever the masjid or circle is running.');
insert into public.question_options (question_id, key, cluster, order_index) values ('6e443160-fcac-4d10-a665-36453237e2ad', 'd', 'individual', 4);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('6e443160-fcac-4d10-a665-36453237e2ad', 'd', 'en', 'Not something I plan formally', 'It happens as life brings it.');
insert into public.questions (id, key, topic_id, order_index, default_importance) values ('e193d40a-2db7-4ba1-b729-d70531fb8cea', 'faith-04', '8ff239e3-f9a2-415a-ad5d-073d83646bf7', 4, 'medium');
insert into public.question_translations (question_id, locale, text, starter_aligned, starter_discuss) values ('e193d40a-2db7-4ba1-b729-d70531fb8cea', 'en', 'If one of us wanted to change something about how we practise, what would you expect?', 'You have landed in a similar place on this one. Compare what that would look like in an ordinary week, so the shared expectation is concrete.', 'Practice changes over a marriage, usually gradually. Agree on how you''d want to hear about it, rather than what the change should be.');
insert into public.question_options (question_id, key, cluster, order_index) values ('e193d40a-2db7-4ba1-b729-d70531fb8cea', 'a', 'joint', 1);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('e193d40a-2db7-4ba1-b729-d70531fb8cea', 'a', 'en', 'We decide together', 'It affects both of us, so we agree it.');
insert into public.question_options (question_id, key, cluster, order_index) values ('e193d40a-2db7-4ba1-b729-d70531fb8cea', 'b', 'joint', 2);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('e193d40a-2db7-4ba1-b729-d70531fb8cea', 'b', 'en', 'Consulted, but it''s personal', 'Tell me, but it''s ultimately yours.');
insert into public.question_options (question_id, key, cluster, order_index) values ('e193d40a-2db7-4ba1-b729-d70531fb8cea', 'c', 'individual', 3);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('e193d40a-2db7-4ba1-b729-d70531fb8cea', 'c', 'en', 'Each person''s own business', 'I wouldn''t expect a conversation.');
insert into public.question_options (question_id, key, cluster, order_index) values ('e193d40a-2db7-4ba1-b729-d70531fb8cea', 'd', 'individual', 4);
insert into public.question_option_translations (question_id, option_key, locale, label, description) values ('e193d40a-2db7-4ba1-b729-d70531fb8cea', 'd', 'en', 'We''d seek guidance together', 'Ask someone knowledgeable, as a pair.');
