insert into public.question_translations (question_id, locale, text, starter_aligned, starter_discuss) values ('81b8d403-53e6-4e36-aaf1-a3ca11c9cb20', 'en', 'How do you feel about differences between us in how we practise?', 'You have landed in a similar place on this one. Compare what that would look like in an ordinary week, so the shared expectation is concrete.', 'This one is about expectation, not level. Talk about what you''d each find hard to live alongside, rather than who is doing more.');
